import{_ as o,o as s,c as t,a5 as r}from"./chunks/framework.DvE3tBec.js";const u=JSON.parse('{"title":"openEO API 1.3.0 and openEO Processes 2.0.0 RC2 released","description":"","frontmatter":{"news":true,"title":"openEO API 1.3.0 and openEO Processes 2.0.0 RC2 released","date":"2026-02-03T00:00:00.000Z","author":"Matthias Mohr","aside":false},"headers":[],"relativePath":"news/2026-02-03-new-openeo-versions-130-200rc2.md","filePath":"news/2026-02-03-new-openeo-versions-130-200rc2.md","lastUpdated":1770123579000}'),a={name:"news/2026-02-03-new-openeo-versions-130-200rc2.md"};function n(i,e,c,l,d,p){return s(),t("div",null,[...e[0]||(e[0]=[r('<p>Today, we have released the new version 1.3.0 of the openEO API. At the same time, we&#39;ve also released openEO Processes 2.0.0-rc.2.</p><p>These releases continue the journey towards first-class vector data cube support, while also bringing a number of quality-of-life improvements for implementers (back-ends) and consumers (clients).</p><p>Back-ends and clients are advised to check their implementations against the new specifications and update accordingly.</p><p>Below you can find details about the individual releases:</p><h2 id="openeo-api-v1-3-0" tabindex="-1">openEO API v1.3.0 <a class="header-anchor" href="#openeo-api-v1-3-0" aria-label="Permalink to &quot;openEO API v1.3.0&quot;">​</a></h2><p>openEO API 1.3.0 contains a set of improvements, clarifications and new capabilities, with a strong focus on authentication, batch job metadata and interoperability.</p><ul><li><a href="https://api.openeo.org/1.3.0" target="_blank" rel="noreferrer">API documentation</a></li></ul><p>Please consult the <strong><a href="https://github.com/Open-EO/openeo-api/tree/1.3.0/CHANGELOG.md" target="_blank" rel="noreferrer">changelog</a></strong> for the full list of changes and additions.</p><h3 id="api-highlights" tabindex="-1">API Highlights <a class="header-anchor" href="#api-highlights" aria-label="Permalink to &quot;API Highlights&quot;">​</a></h3><ul><li><strong>New extensions</strong>: <ul><li><a href="https://github.com/Open-EO/openeo-api/tree/1.3.0/extensions/processing-parameters" target="_blank" rel="noreferrer">Processing Parameters Extension</a></li><li><a href="https://github.com/Open-EO/openeo-api/tree/1.3.0/extensions/remote-process-definition" target="_blank" rel="noreferrer">Remote Process Definition Extension</a></li><li><a href="https://github.com/Open-EO/openeo-api/tree/1.3.0/extensions/workspaces" target="_blank" rel="noreferrer">Workspaces Extension</a></li></ul></li><li><strong>Authentication updates:</strong> Support for standard JSON Web Tokens (JWT) as Bearer tokens, while deprecating the openEO-specific token format.</li><li><strong>Batch job metadata improvements:</strong> Additional timestamps such as <code>queued</code>, <code>started</code> and <code>unpublished</code>, a status diagram, and extended timestamps in STAC results.</li><li><strong>Improved logging:</strong> Added <code>stacktrace</code> to log entries to simplify debugging.</li><li><strong>Discovery and process metadata tightened:</strong> <code>GET /</code> now requires the fields <code>type</code> and <code>conformsTo</code>; <code>GET /processes</code> adds a <code>version</code> property for processes; <code>GET /</code> also adds a new <code>web-editor</code> link relation type.</li><li><strong>Deprecations:</strong> STAC 0.9.x is deprecated.</li></ul><p>Feedback is more than welcome. Please report issues and questions through the <a href="https://github.com/Open-EO/openeo-api/issues" target="_blank" rel="noreferrer">GitHub issue tracker</a>. The next version is likely v1.4.0, work has started.</p><h2 id="openeo-processes-v2-0-0-rc-2" tabindex="-1">openEO Processes v2.0.0-rc.2 <a class="header-anchor" href="#openeo-processes-v2-0-0-rc-2" aria-label="Permalink to &quot;openEO Processes v2.0.0-rc.2&quot;">​</a></h2><p>openEO Processes 2.0.0-rc.2 is the second release candidate of the upcoming 2.0 release series. It builds on the 2.0 work that introduced the <code>datacube</code> data type and vector cube support, and continues to improve process definitions, consistency and implementability.</p><p>Please note that some changes are breaking changes. Make sure to review the changelog carefully before updating implementations.</p><ul><li><a href="https://processes.openeo.org/2.0.0-rc.2" target="_blank" rel="noreferrer">Processes documentation</a></li></ul><p>Please consult the <strong><a href="https://github.com/Open-EO/openeo-processes/tree/2.0.0-rc.2/CHANGELOG.md" target="_blank" rel="noreferrer">changelog</a></strong> for a full list of changes and additions.</p><h3 id="processes-highlights" tabindex="-1">Processes Highlights <a class="header-anchor" href="#processes-highlights" aria-label="Permalink to &quot;Processes Highlights&quot;">​</a></h3><ul><li><strong>Implementation support:</strong> A new implementation guide for implementing OGC API - Processes in openEO, plus a dedicated set of unit tests.</li><li><strong>New processes:</strong><ul><li><code>export_collection</code>, <code>export_workspace</code></li><li><code>run_ogcapi</code>, <code>run_ogcapi_externally</code></li><li><code>stac_modify</code></li><li><code>text_find</code></li></ul></li><li><strong>More stable processes:</strong> <code>apply_polygon</code>, <code>date_between</code>, <code>date_shift</code>, <code>filter_labels</code> and <code>inspect</code> are now marked as stable.</li><li><strong>Behaviour and consistency updates:</strong><ul><li><code>save_results</code> returns the STAC resource (instead of boolean <code>true</code>).</li><li><code>all</code> returns <code>true</code> for empty arrays; <code>any</code> returns <code>false</code> for empty arrays.</li><li><code>apply_polygon</code> renamed parameter <code>polygons</code> to <code>geometries</code>.</li><li><code>clip</code> throws an exception if min &gt; max. <a href="https://github.com/Open-EO/openeo-processes/issues/472" target="_blank" rel="noreferrer">#472</a></li><li><code>date_difference</code> allows <code>week</code> as a unit.</li><li><code>is_nan</code> returns <code>false</code> for non-numerical data types. <a href="https://github.com/Open-EO/openeo-processes/issues/486" target="_blank" rel="noreferrer">#486</a></li></ul></li><li><strong>Clarifications and fixes across the board:</strong> Improved handling of <code>NaN</code>, <code>null</code> and no-data values, added uniqueness constraints for various array-typed parameters, and numerous targeted fixes (e.g. geometry dimension type clarifications).</li></ul><p>As this is a release candidate, feedback is more than welcome. Please report issues and questions through the <a href="https://github.com/Open-EO/openeo-processes/issues" target="_blank" rel="noreferrer">GitHub issue tracker</a>. The next version is likely v2.0.0 (stable).</p>',19)])])}const g=o(a,[["render",n]]);export{u as __pageData,g as default};
